export function Contrast({
  pair = "{{pair}}",
  largeText = {{largeText}},
  radius = {{radius}},
  sampleText = "{{sampleText}}",
}) {
  const info = {
    "ink-paper": { color: "#241430", ratio: "16.1:1", pass: true },
    "gold-paper": { color: "#E8A020", ratio: "2.1:1", pass: false },
    "mint-paper": { color: "#A8E6C1", ratio: "1.3:1", pass: false },
  }[pair];
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 300 }}
      role="img" aria-label="A text sample against its background, with the measured WCAG contrast ratio and pass or fail stated as text">
      <div style={{ padding: 20, textAlign: "center", boxSizing: "border-box", background: "#FAF7F2", border: "1.5px solid #24143022",
        borderRadius: radius, color: info.color, fontSize: largeText ? 24 : 15, fontWeight: largeText ? 700 : 400 }}>
        {sampleText}
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430cc" }}>
        Required for {largeText ? "large" : "normal"} text: {largeText ? "3.0" : "4.5"}:1
      </p>
      <p style={{ marginTop: 4, fontSize: 13, fontWeight: 700, color: info.pass ? "#1a7a3d" : "#b3261e" }}>
        Measured ratio: {info.ratio} &mdash; {info.pass ? "PASS" : "FAIL"}
      </p>
    </div>
  );
}
